/* Returns the camera slot (gCameraSlotsLvl) whose id is id, or 0 when none.
   Adapted from Lombyte's project (GPL-3.0) for PAL: src/overlays/shared/gameplay/camera/001eb188.c, FUN_L00_001eb1f8. */
Camera *find_camera_record_by_id(int id) {
    s32 p;
    s32 e;
    s16 v;
    p = (s32)&gCameraSlotsLvl[0];
    e = p + 0x1E00; /* 48 slots */
    for (;;) {
        v = ((Camera *)p)->id;
        if (v != id) {
            p += 0xA0;
            if (p < e)
                continue;
            return 0;
        }
        return (Camera *)p;
    }
}
