/* Camera update, once per frame: count the frame, run the camera steps, take the view from the target camera (mode 3
   blends it) unless frozen, refresh the angles and the derived vectors. Level copy of update_camera. Joined with
   Camera_UpdateFrame_store_tail and Camera_UpdateFrame_body_tail (config/overlays/joined.tsv). */
void Camera_UpdateFrame(void) {
    CameraSystem *c;
    Camera *target;
    CameraShake *v;
    float m[16];

    if (cinematic_mode == 5) {
        if (vendor_menu_field_40 != 0) {
            return;
        }
        {
            CamBlend *b = &gCameraLvl.blend;
            b->phase = 0;
            b->kind = 0;
        }
    }
    c = &gCameraLvl;
    c->frames++;
    advance_timed_camera_control();
    Camera_PickCollisionMasksLvl();
    update_camera_tracking_state();
    UpdateAllCamerasLvl();
    target = c->current;
    if ((unsigned short)(c->blend.phase - 1) < 2) {
        Camera_CaptureTransform(c->previous);
    }
    if (c->blend.phase == 3) {
        update_camera_blend((char *)target);
    } else {
        DebugFreeCam *st = &gDebugFreeCamLvl;
        if (st->active != 0) {
            goto frozen;
        }
        qcopy(&c->pos, &target->pos);
        qcopy(&c->matrix[0], &target->basis[0]);
        qcopy(&c->matrix[1], &target->basis[1]);
        qcopy(&c->matrix[2], &target->basis[2]);
    }
    {
        DebugFreeCam *st = &gDebugFreeCamLvl;
        if (st->active == 0) {
            copy_matrix_rotation(m, gCameraLvl.matrix);
            matrix_to_euler(m, &gCameraLvl.rot);
        }
    }
frozen:
    v = gCameraLvl.shake;
    apply_camera_shake((char *)&v[0], 0);
    apply_camera_shake((char *)&v[1], 1);
    update_camera_underwater_flag();
    update_camera_environment_from_regions((char *)v - 0x20); /* &gCameraLvl.pos */
    if (draw_map51[0] != 0) {
        FastVecCross((char *)v + 0x200, (char *)v + 0x210, (char *)v + 0x1F0); /* matrix[1] = matrix[2] x matrix[0] */
    }
}
